-- Release A: actor/creator separation, direct DML, lifecycle and internal RPC surface.
-- Every probe rolls back its own effects, including before the fix.
begin;
set search_path = public, extensions;
select no_plan();
create schema release_security_test;
grant usage on schema release_security_test to public;
create function release_security_test.probe(statement text) returns text
language plpgsql security invoker as $$
declare affected bigint;
begin
  begin
    execute statement;
    get diagnostics affected = row_count;
    raise sqlstate 'PT001';
  exception
    when sqlstate 'PT001' then return affected::text;
    when others then return sqlstate;
  end;
end;
$$;
